// RFC 8291 (aes128gcm), RFC 8292 (VAPID), лише стандартний Node.js crypto.


const b64u = (buf) => Buffer.from(buf).toString('base64url');
const from64 = (s) => Buffer.from(s, 'base64url');

function generateVapidKeys() {
  const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
  const jwk = publicKey.export({ format: 'jwk' });
  const uncompressed = Buffer.concat([Buffer.from([4]), from64(jwk.x), from64(jwk.y)]);
  return { publicKey: b64u(uncompressed), privateKey: privateKey.export({ type: 'pkcs8', format: 'pem' }) };
}

function validateSubscription(sub) {
  if (!sub || typeof sub !== 'object') return false;
  if (typeof sub.endpoint !== 'string' || sub.endpoint.length > 1400) return false;
  let url;
  try { url = new URL(sub.endpoint); } catch { return false; }
  if (url.protocol !== 'https:' || url.username || url.password || url.port) return false;
  const host = url.hostname.toLowerCase();
  const allowed = host === 'fcm.googleapis.com' || host === 'updates.push.services.mozilla.com' || host === 'push.services.mozilla.com' || host === 'web.push.apple.com' || host.endsWith('.push.apple.com') || host.endsWith('.notify.windows.com');
  if (!allowed) return false;
  for (const key of ['p256dh','auth']) {
    if (typeof sub.keys?.[key] !== 'string' || sub.keys[key].length > 150 || !/^[A-Za-z0-9_-]+={0,2}$/.test(sub.keys[key])) return false;
  }
  try {
    if (from64(sub.keys.p256dh).length !== 65 || from64(sub.keys.auth).length !== 16) return false;
    if (from64(sub.keys.p256dh)[0] !== 4) return false;
  } catch { return false; }
  return true;
}

function encryptPayload(subscription, data, saltInput, ephemeralPrivate) {
  const clientPublic = from64(subscription.keys.p256dh);
  const authSecret = from64(subscription.keys.auth);
  const server = crypto.createECDH('prime256v1');
  if (ephemeralPrivate) server.setPrivateKey(ephemeralPrivate); else server.generateKeys();
  const serverPublic = server.getPublicKey();
  const shared = server.computeSecret(clientPublic);
  const keyInfo = Buffer.concat([Buffer.from('WebPush: info\0'), clientPublic, serverPublic]);
  const ikm = crypto.hkdfSync('sha256', shared, authSecret, keyInfo, 32);
  const salt = saltInput || crypto.randomBytes(16);
  const contentKey = Buffer.from(crypto.hkdfSync('sha256', ikm, salt, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(crypto.hkdfSync('sha256', ikm, salt, Buffer.from('Content-Encoding: nonce\0'), 12));
  const plaintext = Buffer.concat([Buffer.from(data, 'utf8'), Buffer.from([2])]);
  if (plaintext.length > 3993) throw new Error('Push payload too long');
  const cipher = crypto.createCipheriv('aes-128-gcm', contentKey, nonce);
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final(), cipher.getAuthTag()]);
  const recordSize = Buffer.alloc(4); recordSize.writeUInt32BE(4096);
  return Buffer.concat([salt, recordSize, Buffer.from([serverPublic.length]), serverPublic, encrypted]);
}

function vapidJwt(endpoint, keys, subject) {
  const aud = new URL(endpoint).origin;
  const now = Math.floor(Date.now() / 1000);
  const header = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  const payload = b64u(JSON.stringify({ aud, exp: now + 3600, sub: subject }));
  const input = `${header}.${payload}`;
  const signature = crypto.sign('sha256', Buffer.from(input), { key: keys.privateKey, dsaEncoding: 'ieee-p1363' });
  return `${input}.${b64u(signature)}`;
}

async function sendPush(subscription, message, keys, subject = 'mailto:notifications@example.org', fetchImpl = fetch) {
  if (!validateSubscription(subscription)) throw new Error('Непідтримуваний endpoint');
  const body = encryptPayload(subscription, JSON.stringify(message));
  const jwt = vapidJwt(subscription.endpoint, keys, subject);
  const response = await fetchImpl(subscription.endpoint, {
    method: 'POST',
    headers: {
      Authorization: `vapid t=${jwt}, k=${keys.publicKey}`,
      'Content-Encoding': 'aes128gcm',
      'Content-Type': 'application/octet-stream',
      'TTL': '3600',
      'Urgency': message.kind === 'urgent' ? 'high' : 'normal'
    },
    body,
    signal: AbortSignal.timeout(9000)
  });
  if (!response.ok) {
    const err = new Error(`Push server HTTP ${response.status}`);
    err.status = response.status;
    throw err;
  }
  return response.status;
}


const DATA_DIR = path.resolve(process.env.DATA_DIR || '/data');
const STATE_FILE = path.join(DATA_DIR, 'state.json');
const KEY_FILE = path.join(DATA_DIR, 'vapid.json');
